object.value:
={{ {
  "client_id": $('Vitascience Webhook').first().json.client_id,
  "analysis_id": $('Vitascience Webhook').first().json.analysis_id || $runIndex,
  "timestamp": $now,
  "vsl_metadata": {
    "length_characters": $('Vitascience Webhook').first().json.vsl_text.length,
    "length_words": $('Vitascience Webhook').first().json.vsl_text.split(' ').length,
    "product_category": $('Vitascience Webhook').first().json.product_category || "health_supplement"
  },
  "eugene_analysis": $('Complete Eugene Analysis').first().json,
  "business_insights": {
    "conversion_potential": $('Complete Eugene Analysis').first().json.problems.score_geral_copy >= 7 ? "Alto" : $('Complete Eugene Analysis').first().json.problems.score_geral_copy >= 5 ? "Médio" : "Baixo",
    "priority_fixes": $('Complete Eugene Analysis').first().json.improvements.melhorias_quick_wins.slice(0, 3),
    "investment_recommendation": $('Complete Eugene Analysis').first().json.problems.score_geral_copy < 6 ? "Reescrita completa recomendada" : "Otimizações pontuais suficientes",
    "target_audience_alignment": $('Complete Eugene Analysis').first().json.consciousness.nivel_identificado === $('Complete Eugene Analysis').first().json.consciousness.nivel_ideal_sugerido ? "Alinhado" : "Desalinhado"
  }
} }}

